import type { McapFixtureOptions } from "./types";

/** Bump when the generated bytes change for the same options (invalidates cached fixtures). */
export const MCAP_FIXTURE_GENERATOR_VERSION = 1;

/** Name of the manifest written next to the generated files. */
export const MCAP_FIXTURE_MANIFEST = "manifest.json";

/** First message log time (fixed, so output is byte-for-byte reproducible). */
export const MCAP_FIXTURE_START_TIME_NS = 1_700_000_000_000_000_000n;

/** Defaults of every `McapFixtureOptions` field. */
export const DEFAULT_MCAP_FIXTURE_OPTIONS: Required<McapFixtureOptions> = {
  fileCount: 4,
  durationSec: 10,
  rateHz: 200,
  payloadBytes: 1024,
  topic: "/benchmark/multi",
  chunkSize: 256 * 1024,
};

/** JSON schema of the generated messages. */
export const MCAP_FIXTURE_MESSAGE_SCHEMA = {
  type: "object",
  properties: {
    value: { type: "number" },
    seq: { type: "integer" },
    payload: { type: "string" },
  },
};

/**
 * Forces ANGLE's SwiftShader (CPU) backend, as `e2e/fixtures/electron.ts` does. Required on Linux:
 * under xvfb (CI, ubuntu-latest) Electron's default GL path (Mesa llvmpipe) fails WebGL context
 * creation, while SwiftShader yields WebGL 2 (ANGLE Vulkan / SwiftShader driver).
 */
export const SWIFTSHADER_WEBGL_SWITCHES: readonly string[] = [
  "--use-gl=angle",
  "--use-angle=swiftshader",
  "--enable-unsafe-swiftshader",
];

/** Marker switch identifying this run's browser process tree (ps fallback of the collector). */
export const RUN_MARKER_SWITCH = "--lichtblick-benchmark-run";
